// Central image manifest. Every image on the site is referenced by key, so
// replacing the illustrated plates with licensed photography means editing
// this file only (see docs/IMAGERY.md).
//
// The current set are original illustrated plates generated by
// scripts/plates. They depict landscapes in general terms and are not
// pictures of specific properties, people or partners.

export type ImageAsset = {
  src: string;
  alt: string;
  width: number;
  height: number;
  /** CSS object-position used when the image is cropped. */
  position?: string;
};

const plate = (name: string, alt: string, width = 1800, height = 1200, position?: string): ImageAsset => ({
  src: `/images/plates/${name}.jpg`,
  alt,
  width,
  height,
  position,
});

